const BASE = import.meta.env.BASE_URL;
const SCHOOL = "https://jwxt.sysu.edu.cn/jwxt/mk/schedule-web/#/studentTimeTabPrint?code=jwxsd_xskbcx";

type MainTab = "today" | "plan" | "me";
type PlanMode = "week" | "month" | "tasks" | "notes";

function useRoute() {
  const get = () => location.hash.replace(/^#/, "") || "/today";
  const [route, setRoute] = useState(get);
  useEffect(() => { const change = () => setRoute(get()); addEventListener("hashchange", change); return () => removeEventListener("hashchange", change); }, []);
  const go = (path: string, replace = false) => { if (replace) history.replaceState(null, "", `#${path}`); else location.hash = path; setRoute(path); window.scrollTo({ top: 0, behavior: "instant" }); };
  return { route, go };
}

function Icon({ name }: { name: string }) {
  const icons: Record<string, React.ReactNode> = {
    today: <><path d="M5 7h14M8 3v4m8-4v4M5 5h14v16H5z"/><path d="M8 11h3v3H8z"/></>,
    plan: <><path d="M5 4h14v16H5zM9 4v16M5 9h14"/><path d="M12 13h4M12 16h4"/></>,
    me: <><circle cx="12" cy="8" r="4"/><path d="M4 21c1-5 4-7 8-7s7 2 8 7"/></>,
    back: <path d="m15 18-6-6 6-6"/>, plus: <path d="M12 5v14M5 12h14"/>,
    check: <path d="m5 12 4 4L19 6"/>, focus: <><circle cx="12" cy="12" r="8"/><path d="M12 8v5l3 2"/></>,
    settings: <><circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/></>,
    note: <><path d="M5 3h14v18H5z"/><path d="M8 8h8M8 12h8M8 16h5"/></>,
  };
  return <svg className="icon" viewBox="0 0 24 24" aria-hidden="true">{icons[name] ?? icons.plan}</svg>;
}

function Button({ children, kind = "primary", icon, onClick, type = "button", ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { kind?: "primary" | "secondary" | "text" | "danger"; icon?: string }) {
  return <button type={type} className={`button ${kind}`} onClick={onClick} {...props}>{icon && <Icon name={icon}/>}<span>{children}</span></button>;
}

function PageHeader({ title, eyebrow, back, action }: { title: string; eyebrow?: string; back?: () => void; action?: React.ReactNode }) {
  return <header className="page-header">{back && <button className="icon-button" onClick={back} aria-label="返回"><Icon name="back"/></button>}<div><p>{eyebrow}</p><h1>{title}</h1></div>{action && <div className="page-action">{action}</div>}</header>;
}

function Modal({ title, close, children }: { title: string; close: () => void; children: React.ReactNode }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { ref.current?.showModal(); }, []);
  return <dialog ref={ref} onCancel={(e) => { e.preventDefault(); close(); }}><header><h2>{title}</h2><button className="text-button" onClick={close}>关闭</button></header>{children}</dialog>;
}

function Toast({ value, clear }: { value: string; clear: () => void }) {
  useEffect(() => { if (!value) return; const id = setTimeout(clear, 3600); return () => clearTimeout(id); }, [value, clear]);
  return value ? <div className="toast" role="status"><span>{value}</span><button onClick={clear} aria-label="关闭提示">×</button></div> : null;
}

function Segmented<T extends string>({ value, values, onChange }: { value: T; values: [T, string][]; onChange: (v: T) => void }) {
  return <div className="segmented">{values.map(([key, label]) => <button key={key} aria-pressed={value === key} onClick={() => onChange(key)}>{label}</button>)}</div>;
}

function Field({ label, help, children }: { label: string; help?: string; children: React.ReactNode }) {
  return <label className="field"><span>{label}</span>{children}{help && <small>{help}</small>}</label>;
}

function Avatar({ data, size = 52 }: { data: WebAppData; size?: number }) {
  const [url, setUrl] = useState("");
  useEffect(() => { let alive = true; let local = ""; readAsset(data.profile.avatarAssetId).then((blob) => { if (alive && blob) { local = URL.createObjectURL(blob); setUrl(local); } }); return () => { alive = false; if (local) URL.revokeObjectURL(local); }; }, [data.profile.avatarAssetId]);
  return <span className="avatar" style={{ width: size, height: size }}>{url ? <img src={url} alt="个人头像"/> : (data.profile.nickname || "同").slice(0, 1)}</span>;
}

export function App() {
  const { route, go } = useRoute();
  const [data, setData] = useState<WebAppData>(defaultData);
  const [ready, setReady] = useState(false);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [online, setOnline] = useState(navigator.onLine);
  const [standalone, setStandalone] = useState(matchMedia("(display-mode: standalone)").matches || (navigator as any).standalone === true);
  const [installHelp, setInstallHelp] = useState(false);
  const [deferredInstall, setDeferredInstall] = useState<any>(null);
  const [launchDone, setLaunchDone] = useState(sessionStorage.getItem("launch-done") === "1");
  const { offlineReady: [offlineReady], needRefresh: [needRefresh], updateServiceWorker } = useRegisterSW({
    onRegisterError: () => setMessage("离线资源尚未准备好，请联网后重试。"),
  });
  useEffect(() => {
    readData().then(setData).catch(() => setMessage("无法读取本机数据，请检查 Safari 的网站存储设置。")).finally(() => setReady(true));
    const net = () => setOnline(navigator.onLine); const installed = () => { setStandalone(true); setDeferredInstall(null); };
    const install = (e: Event) => { e.preventDefault(); setDeferredInstall(e); };
    addEventListener("online", net); addEventListener("offline", net); addEventListener("appinstalled", installed); addEventListener("beforeinstallprompt", install);
    return () => { removeEventListener("online", net); removeEventListener("offline", net); removeEventListener("appinstalled", installed); removeEventListener("beforeinstallprompt", install); };
  }, []);
  useEffect(() => { document.documentElement.dataset.theme = data.settings.theme; document.documentElement.dataset.mode = data.settings.darkMode; }, [data.settings.theme, data.settings.darkMode]);
  async function commit(next: WebAppData, note?: string) { setBusy(true); try { const saved = await saveData(next); setData(saved); syncPushIfEnabled(saved).catch(() => setMessage("内容已保存；推送提醒暂未同步，请在设置中检查服务器。")); if (note) setMessage(note); } finally { setBusy(false); } }
  const mainTab: MainTab = route.startsWith("/plan") ? "plan" : route.startsWith("/me") ? "me" : "today";
  const detail = !["/today", "/plan", "/me"].includes(route);

  if (!ready) return <div className="boot"><span className="boot-mark">课</span><p>正在打开你的课表</p></div>;
  if (data.settings.launch.enabled && !launchDone && !route.includes("from-notification")) return <LaunchGate data={data} done={() => { sessionStorage.setItem("launch-done", "1"); setLaunchDone(true); }}/>
  return <>
    <div className={`app-shell ${detail ? "detail-open" : ""}`}>
      <header className="masthead"><button className="brand" onClick={() => go("/today")}><span>中大课表</span><small>xiaoyle 制作</small></button><span className={`connection ${online ? "" : "offline"}`}>{online ? (offlineReady ? "离线已就绪" : "在线") : "离线查看"}</span></header>
      {needRefresh && <div className="update-banner"><span>新版本已准备好，刷新后生效。</span><Button kind="secondary" onClick={() => updateServiceWorker(true)}>立即刷新</Button></div>}
      <main>
        {route === "/today" && <TodayPage data={data} go={go}/>} 
        {route === "/plan" && <PlanPage data={data} commit={commit} go={go}/>} 
        {route === "/me" && <MePage data={data} go={go} standalone={standalone} install={() => deferredInstall ? deferredInstall.prompt() : setInstallHelp(true)}/>} 
        {route === "/import" && <ImportPage data={data} commit={commit} back={() => go("/me")} busy={busy} setBusy={setBusy} message={setMessage}/>} 
        {route === "/course/new" && <CourseEditor data={data} commit={commit} back={() => history.back()}/>} 
        {route.startsWith("/course/edit/") && <CourseEditor data={data} commit={commit} back={() => history.back()} id={decodeURIComponent(route.slice(13))}/>} 
        {route === "/task/new" && <TaskEditor data={data} commit={commit} back={() => history.back()}/>} 
        {route.startsWith("/task/edit/") && <TaskEditor data={data} commit={commit} back={() => history.back()} id={decodeURIComponent(route.slice(11))}/>} 
        {route === "/notes/new" && <NoteEditor data={data} commit={commit} back={() => history.back()}/>} 
        {route.startsWith("/notes/edit/") && <NoteEditor data={data} commit={commit} back={() => history.back()} id={decodeURIComponent(route.slice(12))}/>} 
        {route.startsWith("/notes/read/") && <NoteReader data={data} go={go} back={() => history.back()} id={decodeURIComponent(route.slice(12))}/>} 
        {route === "/focus" && <FocusPage data={data} commit={commit} back={() => history.back()}/>} 
        {route === "/achievements" && <AchievementPage data={data} commit={commit} back={() => go("/me")}/>} 
        {route === "/profile" && <ProfilePage data={data} commit={commit} back={() => go("/me")}/>} 
        {route === "/settings" && <SettingsPage data={data} commit={commit} back={() => go("/me")} go={go} standalone={standalone} install={() => deferredInstall ? deferredInstall.prompt() : setInstallHelp(true)}/>} 
      </main>
    </div>
    {!detail && <nav className="bottom-nav" aria-label="主导航">{(["today","plan","me"] as MainTab[]).map((tab) => <button key={tab} aria-current={mainTab === tab ? "page" : undefined} onClick={() => go(`/${tab}`)}><Icon name={tab}/><span>{tab === "today" ? "今日" : tab === "plan" ? "计划" : "我的"}</span></button>)}</nav>}
    <Toast value={message} clear={() => setMessage("")}/>
    {installHelp && <Modal title="添加到主屏幕" close={() => setInstallHelp(false)}><ol className="steps"><li>使用 Safari 打开本网站。</li><li>点底部“分享”。</li><li>选择“添加到主屏幕”。</li><li>从新图标打开，再导入课表。</li></ol><p className="help">Safari 与主屏幕应用的本地数据可能分开，建议先添加再导入。</p></Modal>}
  </>;
}

function TodayPage({ data, go }: { data: WebAppData; go: (x: string) => void }) {
  const now = shanghaiNow(), date = shanghaiDate();
  const [clock, setClock] = useState(now.getTime());
  useEffect(() => { const id = setInterval(() => setClock(Date.now()), 30000); return () => clearInterval(id); }, []);
  const dayLessons = useMemo(() => allLessons(data, date, date), [data, date]);
  const tasks = useMemo(() => taskOccurrences(data.tasks, addDays(date, -30), addDays(date, 60)).filter((x) => !x.occurrenceCompletedAt), [data.tasks, date]);
  const time = new Intl.DateTimeFormat("en-GB", { timeZone: "Asia/Shanghai", hour: "2-digit", minute: "2-digit", hour12: false }).format(clock);
  const next = dayLessons.find((x) => x.end > time);
  const priority = [...tasks].sort((a,b) => taskRank(a)-taskRank(b) || (a.actualDueAt??"9999").localeCompare(b.actualDueAt??"9999"))[0];
  const week = currentWeek(data, date), progress = Math.round(semesterProgress(data,date)*100);
  const loads = Array.from({length:7},(_,i)=>{const d=addDays(date,i); return {date:d,count:allLessons(data,d,d).length+tasks.filter((x)=>x.occurrenceDate===d).length};});
  const focusMinutes = data.focusSessions.filter((x)=>x.endedAt.slice(0,10)===date).reduce((n,x)=>n+Math.floor(x.focusedSeconds/60),0);
  const minutes=(value:string)=>Number(value.slice(0,2))*60+Number(value.slice(3,5));
  const displayMinutes=(value:number)=>`${String(Math.floor(value/60)).padStart(2,"0")}:${String(value%60).padStart(2,"0")}`;
  const nowMinutes=minutes(time),activeLesson=dayLessons.find(x=>x.start<=time&&x.end>time);
  const gapStart=Math.min(23*60,activeLesson?minutes(activeLesson.end)+10:nowMinutes);
  const nextBoundary=dayLessons.find(x=>minutes(x.start)>gapStart)?.start;
  const gapEnd=nextBoundary?Math.max(gapStart,minutes(nextBoundary)-10):23*60;
  const gapMinutes=Math.max(0,gapEnd-gapStart);
  const gapTask=[...tasks].sort((a,b)=>taskRank(a)-taskRank(b)||(a.actualDueAt??"9999").localeCompare(b.actualDueAt??"9999")).find(x=>(x.estimatedMinutes??30)<=gapMinutes);
  return <>
    <PageHeader eyebrow={dateLabel(date)} title={`今天，${data.profile.nickname === "同学" ? "去上课" : data.profile.nickname}`} action={<Avatar data={data}/>}/>
    <section className="semester-strip"><div><strong>{week && week > 0 ? `第 ${week} 周` : "学期之外"}</strong><span>{data.schedule?.term ?? "尚未导入课表"}</span></div><b>{progress}%</b><i style={{width:`${progress}%`}}/></section>
    <section className="metric-grid"><div><strong>{dayLessons.length}</strong><span>今日课程</span></div><div><strong>{tasks.length}</strong><span>未完成</span></div><div><strong>{focusMinutes}</strong><span>今日专注</span></div></section>
    <section><div className="section-heading"><div><p>此刻最重要</p><h2>{next ? (next.start <= time ? "正在上课" : "下一节课") : "今日节奏"}</h2></div><span>北京时间 {time}</span></div>
      {next ? <LessonCard lesson={next} onClick={() => next.manual && go(`/course/edit/${encodeURIComponent(next.ruleId)}`)} featured/> : <div className="empty compact"><h3>{dayLessons.length ? "今天的课已经结束" : "今天没有课程"}</h3><p>去计划页安排待办，或开始一段专注。</p></div>}
    </section>
    <section className="next-step"><span>下一步</span><h2>{priority?.title ?? next?.title ?? "给今天留一段专注时间"}</h2><p>{priority ? `${taskPriorityName[priority.priority]} · ${timeLabel(priority.actualDueAt)}` : next ? `${next.start} · ${next.location || "地点待定"}` : "从 25 分钟开始，完成一件小事"}</p><Button icon="focus" onClick={() => go("/focus")}>开始专注</Button></section>
    <section className="gap-radar"><div><span>空档雷达</span><h2>{data.activeFocus?"一段专注正在进行":gapMinutes>=10?`${displayMinutes(gapStart)}–${displayMinutes(gapEnd)} · ${gapMinutes} 分钟`:"暂时没有完整空档"}</h2><p>{data.activeFocus?data.activeFocus.title:gapTask?`推荐：${gapTask.title}（约 ${gapTask.estimatedMinutes??30} 分钟）`:gapMinutes>=10?"现有待办都比这段空档更长，可以添加一项短任务。":"课程前后已预留 10 分钟。"}</p></div><Button kind="secondary" onClick={()=>go(data.activeFocus?"/focus":gapTask?"/focus":"/task/new")}>{data.activeFocus?"继续专注":gapTask?"开始":"添加待办"}</Button></section>
    <section><div className="section-heading"><div><p>学习负荷</p><h2>未来 7 天</h2></div></div><div className="load-row">{loads.map((x,i)=><button key={x.date} onClick={()=>go("/plan")}><span>{i===0?"今":"日一二三四五六"[(new Date(`${x.date}T00:00:00Z`).getUTCDay())]}</span><i style={{height:`${Math.max(8,Math.min(48,x.count*8))}px`}}/><strong>{x.count}</strong></button>)}</div></section>
    <section><div className="section-heading"><div><p>今天的安排</p><h2>课程与截止项</h2></div><Button kind="text" icon="plus" onClick={()=>go("/task/new")}>添加</Button></div>{dayLessons.map((x)=><LessonCard key={x.key} lesson={x} onClick={()=>x.manual&&go(`/course/edit/${encodeURIComponent(x.ruleId)}`)}/>)}{tasks.filter((x)=>x.occurrenceDate===date).map((x)=><TaskCard key={x.occurrenceKey} task={x} onClick={()=>go(`/task/edit/${encodeURIComponent(x.id)}`)}/>)}{!dayLessons.length&&!tasks.some((x)=>x.occurrenceDate===date)&&<p className="quiet-line">今天暂时没有安排</p>}</section>
  </>;
}

function LessonCard({ lesson, onClick, featured=false }: { lesson: ReturnType<typeof allLessons>[number]; onClick?:()=>void; featured?:boolean }) {
  return <button className={`lesson-card ${featured?"featured":""}`} onClick={onClick}><time>{lesson.start}<small>{lesson.end}</small></time><div><strong>{lesson.title}</strong><span>{lesson.location || "地点待定"}</span><small>{lesson.teacher || (lesson.manual ? "自建课程" : "任课教师待定")}{lesson.repeatCount && lesson.repeatCount>1 ? ` · 第 ${(lesson.manualIndex??0)+1}/${lesson.repeatCount} 次` : ""}</small></div><b>›</b></button>;
}
function TaskCard({ task, onClick, complete }: { task: TaskOccurrence; onClick:()=>void; complete?:()=>void }) {
  return <article className={`task-card p-${task.priority.toLowerCase()}`}><button className="task-main" onClick={onClick}><span>{taskTypeName[task.type]}</span><strong>{task.title}</strong><small>{task.courseTitle || taskPriorityName[task.priority]} · {timeLabel(task.actualDueAt)}</small></button>{complete&&<button className="round-check" onClick={complete} aria-label="完成任务"><Icon name="check"/></button>}</article>;
}
const taskRank = (x: TaskOccurrence) => { const today=shanghaiDate(); return x.actualDueAt&&x.actualDueAt<`${today}T00:00`?0:x.occurrenceDate===today?1:x.priority==="URGENT"?2:x.actualDueAt?3:x.priority==="IMPORTANT"?4:5; };

function PlanPage({ data, commit, go }: { data: WebAppData; commit:(x:WebAppData,m?:string)=>Promise<void>; go:(x:string)=>void }) {
  const [mode,setMode]=useState<PlanMode>(()=>(sessionStorage.getItem("plan-mode") as PlanMode)||"week"); const [selected,setSelected]=useState(shanghaiDate()); const [week,setWeek]=useState(data.schedule ? Math.max(1,Math.min(lastWeek(data.schedule),currentWeek(data)??1)) : 1);
  const change=(v:PlanMode)=>{setMode(v);sessionStorage.setItem("plan-mode",v)};
  const start=data.schedule?addDays(data.schedule.firstMonday,(week-1)*7):addDays(selected,-(new Date(`${selected}T00:00:00Z`).getUTCDay()||7)+1);
  const complete=async(task:TaskOccurrence)=>{const tasks=data.tasks.map((x)=>x.id!==task.id?x:task.occurrenceKey===x.id?{...x,completedAt:new Date().toISOString()}:{...x,instanceStates:[...x.instanceStates.filter((s)=>s.occurrenceKey!==task.occurrenceKey),{occurrenceKey:task.occurrenceKey,completedAt:new Date().toISOString(),completedSubtaskIds:[]} ]});await commit({...data,tasks},"任务已完成")};
  return <><PageHeader eyebrow="把课程与行动放在同一条时间线上" title="学习计划" action={<Button kind="secondary" icon="plus" onClick={()=>go(mode==="notes"?"/notes/new":mode==="tasks"?"/task/new":"/course/new")}>添加</Button>}/><Segmented value={mode} onChange={change} values={[["week","周课表"],["month","月历"],["tasks","待办"],["notes","笔记"]]}/>
    {mode==="week"&&<WeekPlan data={data} start={start} week={week} setWeek={setWeek} go={go}/>} 
    {mode==="month"&&<MonthPlan data={data} selected={selected} setSelected={setSelected} go={go}/>} 
    {mode==="tasks"&&<TaskList data={data} go={go} complete={complete}/>} 
    {mode==="notes"&&<NoteList data={data} commit={commit} go={go}/>} 
  </>;
}

function WeekPlan({data,start,week,setWeek,go}:{data:WebAppData;start:string;week:number;setWeek:(x:number)=>void;go:(x:string)=>void}) {
  return <div className="plan-stack"><div className="week-switch"><button disabled={week<=1} onClick={()=>setWeek(week-1)}>上一周</button><strong>第 {week} 周</strong><button disabled={!!data.schedule&&week>=lastWeek(data.schedule)} onClick={()=>setWeek(week+1)}>下一周</button></div>{Array.from({length:7},(_,i)=>{const d=addDays(start,i),items=allLessons(data,d,d),tasks=taskOccurrences(data.tasks,d,d);return <section className="day-section" key={d}><div className="day-heading"><div><strong>{"一二三四五六日"[i]}</strong><span>{dateLabel(d,false)}</span></div><small>{items.length+tasks.length} 项</small></div>{items.map((x)=><LessonCard key={x.key} lesson={x} onClick={()=>x.manual&&go(`/course/edit/${encodeURIComponent(x.ruleId)}`)}/>)}{tasks.map((x)=><TaskCard key={x.occurrenceKey} task={x} onClick={()=>go(`/task/edit/${encodeURIComponent(x.id)}`)}/>)}{!items.length&&!tasks.length&&<p className="quiet-line">留白的一天</p>}</section>})}</div>;
}

function MonthPlan({data,selected,setSelected,go}:{data:WebAppData;selected:string;setSelected:(x:string)=>void;go:(x:string)=>void}) {
  const [cursor,setCursor]=useState(selected.slice(0,7)); const first=`${cursor}-01`,offset=(new Date(`${first}T00:00:00Z`).getUTCDay()+6)%7,days=new Date(Number(cursor.slice(0,4)),Number(cursor.slice(5,7)),0).getDate();
  const cells=Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>i-offset+1); const selectedLessons=allLessons(data,selected,selected),selectedTasks=taskOccurrences(data.tasks,selected,selected);
  const move=(n:number)=>{const d=new Date(`${cursor}-01T00:00:00Z`);d.setUTCMonth(d.getUTCMonth()+n);setCursor(d.toISOString().slice(0,7))};
  return <><div className="month-switch"><button onClick={()=>move(-1)}>‹</button><strong>{cursor.replace("-"," 年 ")} 月</strong><button onClick={()=>move(1)}>›</button></div><div className="calendar"><div className="weekdays">{"一二三四五六日".split("").map(x=><span key={x}>{x}</span>)}</div><div className="calendar-grid">{cells.map((day,i)=>{if(day<1||day>days)return <span key={i}/>;const d=`${cursor}-${String(day).padStart(2,"0")}`,count=allLessons(data,d,d).length+taskOccurrences(data.tasks,d,d).length;return <button key={d} className={selected===d?"selected":""} onClick={()=>setSelected(d)}><b>{day}</b>{count>0&&<small>{count}</small>}</button>})}</div></div><section><div className="section-heading"><div><p>{dateLabel(selected)}</p><h2>当天时间线</h2></div><Button kind="text" icon="plus" onClick={()=>go("/task/new")}>添加</Button></div>{selectedLessons.map(x=><LessonCard key={x.key} lesson={x} onClick={()=>x.manual&&go(`/course/edit/${encodeURIComponent(x.ruleId)}`)}/>)}{selectedTasks.map(x=><TaskCard key={x.occurrenceKey} task={x} onClick={()=>go(`/task/edit/${encodeURIComponent(x.id)}`)}/>)}{!selectedLessons.length&&!selectedTasks.length&&<p className="quiet-line">这天还没有安排</p>}</section></>;
}

function TaskList({data,go,complete}:{data:WebAppData;go:(x:string)=>void;complete:(x:TaskOccurrence)=>void}) {
  const [query,setQuery]=useState("");const [filter,setFilter]=useState("ALL"); const from=addDays(shanghaiDate(),-365),to=addDays(shanghaiDate(),730);
  const list=taskOccurrences(data.tasks,from,to).filter(x=>!x.occurrenceCompletedAt&&(filter==="ALL"||x.type===filter)&&(`${x.title} ${x.courseTitle} ${x.note}`.toLowerCase().includes(query.toLowerCase())));
  return <><div className="search-row"><input type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索标题、课程或备注"/><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="ALL">全部类型</option>{Object.entries(taskTypeName).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div><div className="list-stack">{list.map(x=><TaskCard key={x.occurrenceKey} task={x} onClick={()=>go(`/task/edit/${encodeURIComponent(x.id)}`)} complete={()=>complete(x)}/>)}{!list.length&&<div className="empty compact"><h3>没有符合条件的待办</h3><p>添加一项任务，给今天一个清晰的下一步。</p></div>}</div></>;
}

function NoteList({data,commit,go}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;go:(x:string)=>void}) {
  const [category,setCategory]=useState("ALL"),[newCategory,setNewCategory]=useState("");
  const notes=[...data.notes].filter(x=>category==="ALL"||x.categoryId===category).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updatedAt.localeCompare(a.updatedAt));
  const addCategory=async()=>{const title=newCategory.trim();if(!title)return;if(data.categories.some(x=>x.title===title)){setNewCategory("");return}const item={id:uid("category"),title,color:"#176B52",order:data.categories.length};await commit({...data,categories:[...data.categories,item]},"笔记栏目已添加");setCategory(item.id);setNewCategory("")};
  const removeCategory=async(id:string)=>{if(data.categories.length<=1||!confirm("删除这个栏目？栏目中的笔记会移到第一个栏目。"))return;const fallback=data.categories.find(x=>x.id!==id)!;await commit({...data,categories:data.categories.filter(x=>x.id!==id),notes:data.notes.map(x=>x.categoryId===id?{...x,categoryId:fallback.id}:x)},"栏目已删除");setCategory("ALL")};
  return <><div className="category-toolbar"><select value={category} onChange={e=>setCategory(e.target.value)}><option value="ALL">全部栏目</option>{data.categories.map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select><input value={newCategory} onChange={e=>setNewCategory(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")addCategory()}} placeholder="新栏目名称" maxLength={20}/><Button kind="secondary" onClick={addCategory} disabled={!newCategory.trim()}>新增栏目</Button>{category!=="ALL"&&data.categories.length>1&&<Button kind="text" onClick={()=>removeCategory(category)}>删除当前栏目</Button>}</div><div className="note-grid">{notes.map(x=><button className="note-preview" key={x.id} onClick={()=>go(`/notes/read/${encodeURIComponent(x.id)}`)}><span>{data.categories.find(c=>c.id===x.categoryId)?.title??"未分类"}{x.pinned?" · 置顶":""}</span><h2>{x.title}</h2><p>{x.content.replace(/[#>*_`-]/g,"").slice(0,120)||"这篇笔记还没有正文"}</p><small>{new Date(x.updatedAt).toLocaleDateString("zh-CN")}</small></button>)}{!notes.length&&<div className="empty compact"><h3>这个栏目还没有笔记</h3><p>点击右上角“添加”，在完整页面中写下第一篇笔记。</p></div>}</div></>;
}

function MePage({data,go,standalone,install}:{data:WebAppData;go:(x:string)=>void;standalone:boolean;install:()=>void}) {
  const weekStart=addDays(shanghaiDate(),-(new Date(`${shanghaiDate()}T00:00:00Z`).getUTCDay()||7)+1),weekEnd=addDays(weekStart,6); const completed=taskOccurrences(data.tasks,weekStart,weekEnd).filter(x=>x.occurrenceCompletedAt).length,focus=data.focusSessions.filter(x=>x.endedAt.slice(0,10)>=weekStart&&x.endedAt.slice(0,10)<=weekEnd).reduce((n,x)=>n+Math.floor(x.focusedSeconds/60),0);
  return <><section className="profile-hero"><Avatar data={data} size={72}/><div><p>{data.profile.greeting}</p><h1>{data.profile.nickname}</h1><span>{data.profile.dorm||"中大课表 · 本地学习空间"}</span></div><button className="icon-button" onClick={()=>go("/profile")} aria-label="编辑个人资料"><Icon name="settings"/></button></section><section className="review-card"><div><span>本周完成</span><strong>{completed}<small> 项</small></strong></div><div><span>专注时间</span><strong>{focus}<small> 分钟</small></strong></div><div><span>课表周次</span><strong>{currentWeek(data)??"—"}<small> 周</small></strong></div></section><section><div className="section-heading"><div><p>学习印记</p><h2>精选成就</h2></div><Button kind="text" onClick={()=>go("/achievements")}>全部</Button></div><div className="badge-row">{builtInAchievements.slice(0,3).map(x=>{const p=achievementProgress(data,x.id);return <button key={x.id} onClick={()=>go("/achievements")}><span style={{background:x.primary}}>{x.icon}</span><strong>{x.name}</strong><small>{p.value}/{p.target}</small></button>})}</div></section><section className="menu-list"><button onClick={()=>go("/import")}><span><b>课表与导入</b><small>Word、PDF、图片、快捷指令</small></span>›</button><button onClick={()=>go("/settings")}><span><b>个性化与设置</b><small>主题、启动页、备份与提醒</small></span>›</button><button onClick={()=>go("/plan")}><span><b>笔记与待办</b><small>{data.notes.length} 篇笔记 · {data.tasks.length} 项任务</small></span>›</button>{!standalone&&<button onClick={install}><span><b>添加到主屏幕</b><small>以独立 Web App 形式打开</small></span>›</button>}</section><footer>xiaoyle 制作 · 非中山大学官方应用<br/>网页版 0.6.0-beta.1 · 本地优先</footer></>;
}

function ImportPage({data,commit,back,busy,setBusy,message}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void;busy:boolean;setBusy:(x:boolean)=>void;message:(x:string)=>void}) {
  const [firstMonday,setFirstMonday]=useState(data.settings.firstMonday); const [preview,setPreview]=useState<Result|null>(null); const [paste,setPaste]=useState(""); const [pasteHelp,setPasteHelp]=useState(""); const pasteRef=useRef<HTMLTextAreaElement>(null); const [imageDraft,setImageDraft]=useState<ImageImportDraft|null>(null); const [ocrKind,setOcrKind]=useState<ImageImportKind>("AUTO"); const [ocrStatus,setOcrStatus]=useState("");
  const readClipboard=async()=>{try{if(!navigator.clipboard?.readText)throw new Error();const text=await navigator.clipboard.readText();if(!text.trim())throw new Error();setPaste(text);setPasteHelp("");message("已读取剪贴板，可以预览课表")}catch{pasteRef.current?.focus();setPasteHelp("iPhone 未允许网页直接读取剪贴板。请在下方输入框内长按，选择“粘贴”。");message("请在输入框内长按并选择“粘贴”")}};
  const file=async(f:File)=>{setBusy(true);try{monday(firstMonday);if(f.size>12*1024*1024)throw new Error("文件超过 12 MB");const bytes=new Uint8Array(await f.arrayBuffer());let result:Result;if(f.name.toLowerCase().endsWith(".json")){const raw=JSON.parse(new TextDecoder().decode(bytes));if(raw.format==="campus-schedule-backup"){await commit(await importBackup(raw),"完整备份已恢复");return}result=parsePayload(JSON.stringify(raw),firstMonday)}else if(new TextDecoder().decode(bytes.slice(0,5))==="%PDF-")result=await(await import("./pdf")).parsePdf(bytes,firstMonday);else result=parseWord(bytes,firstMonday);setPreview(result)}catch(e){message(e instanceof Error?e.message:"文件导入失败，旧数据未改变")}finally{setBusy(false)}};
  const images=async(files:File[])=>{setBusy(true);try{const draft=await recognizeImages(files,firstMonday,ocrKind,(s,p)=>setOcrStatus(`${s} · ${Math.round(p*100)}%`));setImageDraft(draft);setOcrStatus("")}catch(e){message(e instanceof Error?e.message:"图片识别未完成，旧课表保持不变")}finally{setBusy(false)}};
  const savePreview=async()=>{if(!preview)return;await commit({...data,schedule:preview.schedule,settings:{...data.settings,firstMonday:preview.schedule.firstMonday}},"课表已保存到本机");setPreview(null)};
  return <>
    <PageHeader eyebrow="所有文件都在本机解析" title="导入课表" back={back}/>
    <section className="panel accent-panel"><h2>选择第一教学周</h2><Field label="第 1 周周一" help="仅用于下一次导入；请确认是周一。"><input type="date" value={firstMonday} onChange={e=>setFirstMonday(e.target.value)}/></Field></section>
    <section className="panel"><h2>从文件导入</h2><p>支持学校导出的 Word、DOCX、文字 PDF 和完整备份。</p><label className={`button primary file-button ${busy?"disabled":""}`}>选择文件<input type="file" disabled={busy} accept=".doc,.docx,.pdf,.json" onChange={e=>{const f=e.target.files?.[0];e.target.value="";if(f)file(f)}}/></label></section>
    <section className="panel"><span className="eyebrow">新增 · 本地 OCR</span><h2>从图片识别课表</h2><p>可选择完整课表、长截图、纸质照片或多周手机截图，最多 20 张。</p><Field label="图片类型"><select value={ocrKind} onChange={e=>setOcrKind(e.target.value as ImageImportKind)}><option value="AUTO">自动判断</option><option value="FULL_TERM_TABLE">完整学期课表</option><option value="WEEKLY_MOBILE">手机单周截图</option></select></Field><label className={`button secondary file-button ${busy?"disabled":""}`}>选择课表图片<input type="file" disabled={busy} multiple accept="image/jpeg,image/png,image/webp" onChange={e=>{const fs=[...(e.target.files??[])];e.target.value="";if(fs.length)images(fs)}}/></label>{ocrStatus&&<div className="progress-note"><span className="spinner"/>{ocrStatus}</div>}<p className="help">首次识别会联网下载中文模型；识别在浏览器内完成，原图不上传。</p></section>
    <section className="panel"><span className="eyebrow">SAFARI + 快捷指令</span><h2>从学校网页提取</h2><ol className="steps"><li>在 Safari 登录学校并进入课表查询。</li><li>选择正确学期，等待任意一周课表加载完成。</li><li>从 Safari 共享表单运行“中大课表”，再回来粘贴预览；手机无需寻找“全部”选项。</li></ol><div className="actions"><a className="button secondary" href="https://jwxt.sysu.edu.cn/jwxt/#/login" target="_blank" rel="noreferrer">学校登录 ↗</a><a className="button secondary" href={SCHOOL} target="_blank" rel="noreferrer">课表查询 ↗</a></div><Button kind="secondary" onClick={readClipboard}>读取剪贴板中的课表</Button><textarea ref={pasteRef} className="resize-none" value={paste} onChange={e=>{setPaste(e.target.value);setPasteHelp("")}} onPaste={()=>setPasteHelp("")} placeholder="如果读取失败，请在这里长按并选择“粘贴”" rows={5}/>{pasteHelp&&<p className="warning-text" role="status">{pasteHelp}</p>}<Button disabled={!paste.trim()||busy} onClick={()=>{try{setPreview(parsePayload(paste.trim(),firstMonday))}catch(e){message(e instanceof Error?e.message:"课表数据无效")}}}>读取并预览</Button><a className="text-link" href={`${BASE}shortcut-guide.html?v=20260917`} target="_blank" rel="noreferrer">查看快捷指令配置教程 ↗</a></section>
    {preview&&<Modal title="确认导入" close={()=>!busy&&setPreview(null)}><ImportSummary result={preview}/>{data.schedule&&<p className="notice-inline">确认后替换学校课表，自建课程、任务与笔记不会删除。</p>}<div className="dialog-actions"><Button kind="secondary" onClick={()=>setPreview(null)}>继续核对</Button><Button disabled={busy} onClick={savePreview}>确认保存</Button></div></Modal>}
    {imageDraft&&<ImageReview draft={imageDraft} setDraft={setImageDraft} cancel={()=>setImageDraft(null)} confirm={()=>{try{setPreview(imageDraftToResult(imageDraft));setImageDraft(null)}catch(e){message(e instanceof Error?e.message:"请检查识别结果")}}}/>}</>;
}
function ImportSummary({result}:{result:Result}) { return <><div className="import-summary"><strong>{result.schedule.rules.length}</strong><span>项课程安排</span><strong>{lastWeek(result.schedule)}</strong><span>个教学周</span></div><p>{result.schedule.term} · 第 1 周 {result.schedule.firstMonday}</p>{result.warnings.map(x=><p className="help" key={x}>{x}</p>)}<div className="preview-list">{result.schedule.rules.slice(0,20).map(x=><div key={x.id}><strong>{x.title}</strong><small>星期{"一二三四五六日"[x.weekday-1]} · 第 {x.startPeriod}–{x.endPeriod} 节</small></div>)}</div></>; }
function ImageReview({draft,setDraft,cancel,confirm}:{draft:ImageImportDraft;setDraft:(x:ImageImportDraft)=>void;cancel:()=>void;confirm:()=>void}) { const patch=(id:string,key:string,value:string|number)=>setDraft({...draft,rows:draft.rows.map(x=>x.id===id?{...x,[key]:typeof x[key as keyof typeof x]==="number"?Number(value):value}:x)}); return <Modal title="校对图片识别结果" close={cancel}><div className="review-banner"><strong>{draft.rows.length} 项</strong><span>{draft.kind==="WEEKLY_MOBILE"?`覆盖第 ${draft.capturedWeeks.join("、")} 周`:"完整学期表"}</span></div>{draft.warnings.map(x=><p className="help" key={x}>{x}</p>)}<div className="ocr-list">{draft.rows.map((x,i)=><article className={x.issues.length?"needs-review":""} key={x.id}><header><strong>课程 {i+1}</strong><button onClick={()=>setDraft({...draft,rows:draft.rows.filter(r=>r.id!==x.id)})}>删除</button></header><div className="form-grid"><Field label="周次"><input value={x.weekExpression} onChange={e=>patch(x.id,"weekExpression",e.target.value)}/></Field><Field label="星期"><select value={x.weekday} onChange={e=>patch(x.id,"weekday",e.target.value)}>{"一二三四五六日".split("").map((d,i)=><option value={i+1} key={d}>星期{d}</option>)}</select></Field><Field label="开始节"><input type="number" min="1" max="10" value={x.startPeriod} onChange={e=>patch(x.id,"startPeriod",e.target.value)}/></Field><Field label="结束节"><input type="number" min="1" max="10" value={x.endPeriod} onChange={e=>patch(x.id,"endPeriod",e.target.value)}/></Field></div><Field label="课程名称"><input value={x.title} onChange={e=>patch(x.id,"title",e.target.value)}/></Field><div className="form-grid"><Field label="教师"><input value={x.teacher} onChange={e=>patch(x.id,"teacher",e.target.value)}/></Field><Field label="地点"><input value={x.location} onChange={e=>patch(x.id,"location",e.target.value)}/></Field></div>{x.issues.length>0&&<small className="warning-text">{x.issues.join(" · ")}</small>}</article>)}</div><div className="dialog-actions"><Button kind="secondary" onClick={cancel}>取消</Button><Button disabled={!draft.rows.length} onClick={confirm}>生成导入预览</Button></div></Modal>; }

function CourseEditor({data,commit,back,id}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void;id?:string}) {
  const existing=data.manualLessons.find(x=>x.id===id); const [draft,setDraft]=useState<ManualLesson>(existing??{id:uid("course"),date:shanghaiDate(),title:"",start:"08:00",end:"09:40",teacher:"",location:"",color:"#176B52",repeatCount:1,revisions:[],instanceEdits:[]}); const [repeat,setRepeat]=useState(draft.repeatCount>1); const [error,setError]=useState("");
  const set=<K extends keyof ManualLesson>(k:K,v:ManualLesson[K])=>setDraft({...draft,[k]:v}); const save=async()=>{try{if(!draft.title.trim())throw new Error("请填写课程名称");if(draft.start>=draft.end)throw new Error("结束时间须晚于开始时间");if(repeat&&(draft.repeatCount<2||draft.repeatCount>30))throw new Error("总上课次数须为 2–30 次");const item={...draft,title:draft.title.trim(),repeatCount:repeat?draft.repeatCount:1};await commit({...data,manualLessons:[...data.manualLessons.filter(x=>x.id!==item.id),item]},existing?"课程已更新":"课程已添加");back()}catch(e){setError(e instanceof Error?e.message:"保存失败")}};
  return <><PageHeader eyebrow={existing?"修改自建课程":"添加到学习日历"} title={existing?"编辑课程":"添加课程"} back={back} action={<Button onClick={save}>保存</Button>}/><section className="editor-sheet"><Field label="课程名称"><input autoFocus value={draft.title} onChange={e=>set("title",e.target.value)} placeholder="例如：模拟电路讨论课"/></Field><div className="form-grid"><Field label="日期"><input type="date" value={draft.date} onChange={e=>set("date",e.target.value)}/></Field><Field label="课程颜色"><input type="color" value={draft.color} onChange={e=>set("color",e.target.value)}/></Field><Field label="开始时间"><input type="time" value={draft.start} onChange={e=>set("start",e.target.value)}/></Field><Field label="结束时间"><input type="time" value={draft.end} onChange={e=>set("end",e.target.value)}/></Field></div><label className="switch-row"><span><strong>每周重复</strong><small>在之后每周的同一天生成课程</small></span><input type="checkbox" checked={repeat} onChange={e=>setRepeat(e.target.checked)}/></label>{repeat&&<Field label="总上课次数（含本次）" help={`预计从 ${dateLabel(draft.date,false)} 到 ${dateLabel(addDays(draft.date,(draft.repeatCount-1)*7),false)}`}><input type="number" min="2" max="30" value={draft.repeatCount} onChange={e=>set("repeatCount",Number(e.target.value))}/></Field>}<div className="form-grid"><Field label="教师（选填）"><input value={draft.teacher} onChange={e=>set("teacher",e.target.value)}/></Field><Field label="地点（选填）"><input value={draft.location} onChange={e=>set("location",e.target.value)}/></Field></div>{error&&<p className="field-error">{error}</p>}{existing&&<Button kind="danger" onClick={async()=>{if(confirm("删除这个自建课程系列？")){await commit({...data,manualLessons:data.manualLessons.filter(x=>x.id!==existing.id)},"课程已删除");back()}}}>删除课程</Button>}</section></>;
}
function TaskEditor({data,commit,back,id}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void;id?:string}) {
  const existing=data.tasks.find(x=>x.id===id); const [draft,setDraft]=useState<StudyTask>(existing??{id:uid("task"),title:"",type:"HOMEWORK",courseTitle:"",priority:"NORMAL",note:"",createdAt:new Date().toISOString(),subtasks:[],instanceStates:[],estimatedMinutes:30}); const [repeat,setRepeat]=useState(draft.repeatRule?.kind??"NONE"); const [reminder,setReminder]=useState(draft.remindBeforeMinutes===undefined?"NONE":String(draft.remindBeforeMinutes)); const [subtask,setSubtask]=useState(""); const [error,setError]=useState(""); const set=<K extends keyof StudyTask>(k:K,v:StudyTask[K])=>setDraft({...draft,[k]:v});
  const weekdays=draft.repeatRule?.weekdays??[];const updateRepeat=(patch:Partial<NonNullable<StudyTask["repeatRule"]>>)=>set("repeatRule",{kind:(repeat==="NONE"?"DAILY":repeat) as any,weekdays,...draft.repeatRule,...patch});
  const save=async()=>{try{if(!draft.title.trim())throw new Error("请填写任务标题");if(reminder!=="NONE"&&!draft.dueAt)throw new Error("设置提醒前请填写截止时间");if(repeat!=="NONE"&&!draft.dueAt)throw new Error("重复任务必须设置首次截止时间");if(repeat==="CUSTOM_WEEKDAYS"&&!weekdays.length)throw new Error("请至少选择一个重复星期");if(draft.repeatRule?.endsOn&&draft.dueAt&&draft.repeatRule.endsOn<draft.dueAt.slice(0,10))throw new Error("结束日期不能早于首次截止日期");const task={...draft,title:draft.title.trim(),remindBeforeMinutes:reminder==="NONE"?undefined:Number(reminder),repeatRule:repeat==="NONE"?undefined:{kind:repeat as any,weekdays:repeat==="CUSTOM_WEEKDAYS"?weekdays:[],endsOn:draft.repeatRule?.endsOn}};await commit({...data,tasks:[...data.tasks.filter(x=>x.id!==task.id),task]},existing?"待办已更新":"待办已添加");back()}catch(e){setError(e instanceof Error?e.message:"保存失败")}};
  const addSubtask=()=>{const title=subtask.trim();if(!title)return;set("subtasks",[...draft.subtasks,{id:uid("subtask"),title,order:draft.subtasks.length}]);setSubtask("")};
  const moveSubtask=(index:number,offset:number)=>{const next=[...draft.subtasks],target=index+offset;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];set("subtasks",next.map((x,order)=>({...x,order})))};
  return <><PageHeader eyebrow={existing?"调整任务与提醒":"给下一步一个明确时间"} title={existing?"编辑待办":"添加待办"} back={back} action={<Button onClick={save}>保存</Button>}/><section className="editor-sheet"><Field label="任务标题"><input autoFocus value={draft.title} onChange={e=>set("title",e.target.value)} placeholder="例如：完成电路实验报告"/></Field><div className="form-grid"><Field label="类型"><select value={draft.type} onChange={e=>set("type",e.target.value as any)}>{Object.entries(taskTypeName).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="优先级"><select value={draft.priority} onChange={e=>set("priority",e.target.value as any)}>{Object.entries(taskPriorityName).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="截止时间（可选）"><input type="datetime-local" value={draft.dueAt??""} onChange={e=>set("dueAt",e.target.value||undefined)}/></Field><Field label="预计用时"><select value={draft.estimatedMinutes??30} onChange={e=>set("estimatedMinutes",Number(e.target.value))}>{[15,25,30,45,60,90,120,180].map(x=><option key={x} value={x}>{x} 分钟</option>)}</select></Field><Field label="提醒"><select value={reminder} onChange={e=>setReminder(e.target.value)}><option value="NONE">关闭</option><option value="0">截止时</option><option value="10">提前 10 分钟</option><option value="30">提前 30 分钟</option><option value="60">提前 1 小时</option><option value="1440">提前 1 天</option><option value="4320">提前 3 天</option></select></Field><Field label="重复"><select value={repeat} onChange={e=>{setRepeat(e.target.value);if(e.target.value==="NONE")set("repeatRule",undefined)}}><option value="NONE">不重复</option><option value="DAILY">每天</option><option value="WEEKLY">每周同一天</option><option value="CUSTOM_WEEKDAYS">自选星期</option></select></Field></div>{repeat==="CUSTOM_WEEKDAYS"&&<div className="weekday-picker" aria-label="选择重复星期">{"一二三四五六日".split("").map((label,i)=>{const day=i+1,active=weekdays.includes(day);return <button key={day} aria-pressed={active} onClick={()=>updateRepeat({weekdays:active?weekdays.filter(x=>x!==day):[...weekdays,day].sort()})}>{label}</button>})}</div>}{repeat!=="NONE"&&<Field label="重复结束日期（可选）" help="留空表示持续生成"><input type="date" value={draft.repeatRule?.endsOn??""} onChange={e=>updateRepeat({endsOn:e.target.value||undefined})}/></Field>}<Field label="关联课程（选填）"><input value={draft.courseTitle} onChange={e=>set("courseTitle",e.target.value)} placeholder="课程名称"/></Field><Field label="备注"><textarea className="resize-none" rows={4} value={draft.note} onChange={e=>set("note",e.target.value)} placeholder="交付要求、复习范围或参考资料"/></Field><div className="subtask-editor"><h2>检查清单</h2><div className="subtask-add"><input value={subtask} onChange={e=>setSubtask(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addSubtask()}}} placeholder="添加一个子任务" maxLength={80}/><Button kind="secondary" onClick={addSubtask} disabled={!subtask.trim()}>添加</Button></div>{draft.subtasks.sort((a,b)=>a.order-b.order).map((x,i)=><div className="subtask-row" key={x.id}><span>{x.title}</span><button onClick={()=>moveSubtask(i,-1)} disabled={i===0} aria-label="上移">↑</button><button onClick={()=>moveSubtask(i,1)} disabled={i===draft.subtasks.length-1} aria-label="下移">↓</button><button onClick={()=>set("subtasks",draft.subtasks.filter(s=>s.id!==x.id).map((s,order)=>({...s,order})))} aria-label="删除">×</button></div>)}</div>{error&&<p className="field-error">{error}</p>}{existing&&<Button kind="danger" onClick={async()=>{if(confirm("删除这项待办？")){await commit({...data,tasks:data.tasks.filter(x=>x.id!==existing.id)},"待办已删除");back()}}}>删除待办</Button>}</section></>;
}

function NoteEditor({data,commit,back,id}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void;id?:string}) {
  const existing=data.notes.find(x=>x.id===id);
  const seed:StudyNote=existing??{id:uid("note"),categoryId:data.categories[0]?.id??"",title:"",content:"",pinned:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),contentMode:"PLAIN"};
  const [draft,setDraft]=useState(seed),[appearance,setAppearance]=useState<NoteAppearance>(seed.appearance??data.settings.noteStyle),[customStyle,setCustomStyle]=useState(!!seed.appearance),[dirty,setDirty]=useState(false),[restored,setRestored]=useState(false); const timer=useRef<number | undefined>(undefined);
  useEffect(()=>{if(id)readDraft(id).then(x=>{if(x&&x.note.updatedAt>=seed.updatedAt){setDraft(x.note);setRestored(true)}})},[id]);
  useEffect(()=>{if(!dirty)return;clearTimeout(timer.current);timer.current=window.setTimeout(()=>saveDraft({...draft,appearance:customStyle?appearance:undefined}),700);return()=>clearTimeout(timer.current)},[draft,appearance,customStyle,dirty]);
  const change=(next:StudyNote)=>{setDraft(next);setDirty(true)};
  const leave=()=>{if(!dirty||confirm("有未保存修改，确定放弃？")){deleteDraft(draft.id);back()}};
  const save=async()=>{if(!draft.title.trim()){alert("请填写笔记标题");return}const note={...draft,title:draft.title.trim(),updatedAt:new Date().toISOString(),appearance:customStyle?appearance:undefined};await commit({...data,notes:[...data.notes.filter(x=>x.id!==note.id),note]},"笔记已保存");await deleteDraft(note.id);setDirty(false);back()};
  const paperStyle={"--note-accent":appearance.accent,"--note-scale":appearance.fontScale,"--note-line":appearance.lineSpacing,"--note-padding":`${appearance.pagePadding}px`,"--pattern-alpha":appearance.patternAlpha} as React.CSSProperties;
  return <><PageHeader eyebrow={restored?"已恢复未保存内容":draft.contentMode==="MARKDOWN"?"Markdown 笔记":"增强纯文本"} title={existing?"编辑笔记":"新建笔记"} back={leave} action={<Button onClick={save}>保存</Button>}/><section className={`note-editor paper-${appearance.paper.toLowerCase()}`} style={paperStyle}><div className="note-toolbar"><select value={draft.categoryId} onChange={e=>change({...draft,categoryId:e.target.value})}>{data.categories.map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select><select value={draft.contentMode} onChange={e=>change({...draft,contentMode:e.target.value as any})}><option value="PLAIN">纯文本</option><option value="MARKDOWN">Markdown</option></select><label><input type="checkbox" checked={draft.pinned} onChange={e=>change({...draft,pinned:e.target.checked})}/> 置顶</label></div><input className="note-title-input" value={draft.title} onChange={e=>change({...draft,title:e.target.value})} maxLength={80} placeholder="笔记标题"/><textarea className="note-body-input resize-none" value={draft.content} onChange={e=>change({...draft,content:e.target.value})} maxLength={20000} placeholder="写下课堂要点、复习线索或突然想到的问题…"/><div className="note-meta"><span>{draft.content.length}/20000 字</span><span>{dirty?"正在保存草稿":"已保存"}</span></div></section><section className="panel"><h2>单篇外观</h2><label className="switch-row"><span><strong>单独设置</strong><small>关闭后跟随全局笔记外观</small></span><input type="checkbox" checked={customStyle} onChange={e=>setCustomStyle(e.target.checked)}/></label>{customStyle&&<AppearanceControls value={appearance} onChange={setAppearance}/>}</section></>;
}
function NoteReader({data,go,back,id}:{data:WebAppData;go:(x:string)=>void;back:()=>void;id:string}) {
  const note=data.notes.find(x=>x.id===id); if(!note)return <><PageHeader title="笔记不存在" back={back}/><div className="empty"><p>这篇笔记可能已被删除。</p></div></>;
  const style=note.appearance??data.settings.noteStyle;const paperStyle={"--note-accent":style.accent,"--note-scale":style.fontScale,"--note-line":style.lineSpacing,"--note-padding":`${style.pagePadding}px`,"--pattern-alpha":style.patternAlpha} as React.CSSProperties;
  return <><PageHeader eyebrow={data.categories.find(x=>x.id===note.categoryId)?.title??"笔记"} title={note.title} back={back} action={<Button kind="secondary" onClick={()=>go(`/notes/edit/${encodeURIComponent(note.id)}`)}>编辑</Button>}/><article className={`note-reader paper-${style.paper.toLowerCase()}`} style={paperStyle}>{note.contentMode==="MARKDOWN"?<SafeMarkdown value={note.content}/>:<p className="plain-note">{note.content}</p>}</article></>;
}
function SafeMarkdown({value}:{value:string}) { return <div className="markdown">{value.split("\n").map((line,i)=>{if(/^###\s/.test(line))return <h4 key={i}>{inline(line.slice(4))}</h4>;if(/^##\s/.test(line))return <h3 key={i}>{inline(line.slice(3))}</h3>;if(/^#\s/.test(line))return <h2 key={i}>{inline(line.slice(2))}</h2>;if(/^>\s?/.test(line))return <blockquote key={i}>{inline(line.replace(/^>\s?/,""))}</blockquote>;if(/^[-*]\s/.test(line))return <p className="md-list" key={i}>• {inline(line.slice(2))}</p>;if(/^```/.test(line))return <code key={i}>{line.replace(/^```/,"")}</code>;return <p key={i}>{inline(line)||<br/>}</p>})}</div>; }
function inline(value:string) { const parts=value.split(/(`[^`]+`|\*\*[^*]+\*\*|https:\/\/\S+)/g);return parts.map((x,i)=>x.startsWith("`")?<code key={i}>{x.slice(1,-1)}</code>:x.startsWith("**")?<strong key={i}>{x.slice(2,-2)}</strong>:x.startsWith("https://")?<a key={i} href={x} target="_blank" rel="noreferrer">{x}</a>:x); }
function AppearanceControls({value,onChange}:{value:NoteAppearance;onChange:(x:NoteAppearance)=>void}) { const set=<K extends keyof NoteAppearance>(k:K,v:NoteAppearance[K])=>onChange({...value,[k]:v});return <div className="appearance-controls"><Field label="纸张"><select value={value.paper} onChange={e=>set("paper",e.target.value as any)}><option value="CLEAN">清爽</option><option value="RULED">横线</option><option value="GRID">方格</option><option value="DOT">点阵</option><option value="WARM">暖纸</option></select></Field><Field label="字体"><select value={value.font} onChange={e=>set("font",e.target.value as any)}><option value="SYSTEM">系统无衬线</option><option value="ROUNDED">圆体</option><option value="SERIF">衬线</option></select></Field><Field label={`字号 ${Math.round(value.fontScale*100)}%`}><input type="range" min=".85" max="1.4" step=".05" value={value.fontScale} onChange={e=>set("fontScale",Number(e.target.value))}/></Field><Field label={`行距 ${value.lineSpacing.toFixed(1)}`}><input type="range" min="1.2" max="2" step=".1" value={value.lineSpacing} onChange={e=>set("lineSpacing",Number(e.target.value))}/></Field><Field label="点缀色"><input type="color" value={value.accent} onChange={e=>set("accent",e.target.value)}/></Field></div>; }

function FocusPage({data,commit,back}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void}) {
  const initial=data.activeFocus;const [minutes,setMinutes]=useState(25);const [title,setTitle]=useState(initial?.title??"专注学习");const [active,setActive]=useState<ActiveFocus|null>(initial);const [tick,setTick]=useState(Date.now());
  useEffect(()=>{if(!active||active.status!=="RUNNING")return;const id=setInterval(()=>setTick(Date.now()),1000);return()=>clearInterval(id)},[active]);
  const elapsed=active?active.accumulatedSeconds+(active.status==="RUNNING"?Math.max(0,Math.floor((tick-Date.parse(active.runStartedAt))/1000)):0):0;const total=active?.plannedSeconds??minutes*60;const remain=active?.mode==="STOPWATCH"?elapsed:Math.max(0,total-elapsed);const progress=active?.mode==="STOPWATCH"?0:Math.min(1,elapsed/total);
  useEffect(()=>{if(active?.mode==="COUNTDOWN"&&remain===0&&active.status==="RUNNING")finish()},[remain]);
  const persist=async(next:ActiveFocus|null,note?:string)=>{setActive(next);await commit({...data,activeFocus:next},note)};
  const start=()=>persist({id:uid("focus"),mode:"COUNTDOWN",title:title||"专注学习",plannedSeconds:minutes*60,accumulatedSeconds:0,runStartedAt:new Date().toISOString(),startedAt:new Date().toISOString(),status:"RUNNING"},"专注已开始");
  const pause=()=>active&&persist({...active,accumulatedSeconds:elapsed,status:"PAUSED"},"已暂停");const resume=()=>active&&persist({...active,runStartedAt:new Date().toISOString(),status:"RUNNING"},"继续专注");
  async function finish(){if(!active)return;const ended=new Date().toISOString();await commit({...data,activeFocus:null,focusSessions:[...data.focusSessions,{id:active.id,mode:active.mode,title:active.title,startedAt:active.startedAt,endedAt:ended,focusedSeconds:elapsed,plannedSeconds:active.plannedSeconds,status:"COMPLETED"}]},"这段专注已记录");setActive(null)}
  return <div className="focus-page"><PageHeader eyebrow="页面挂起后会按时间戳恢复" title="校园昼夜光轨" back={back}/><div className="focus-orbit" style={{"--focus-progress":`${progress*360}deg`} as React.CSSProperties}><div className="orb">{active?.mode==="STOPWATCH"?"◷":remain>0?"月":"光"}</div><div className="focus-time">{String(Math.floor(remain/60)).padStart(2,"0")}:{String(remain%60).padStart(2,"0")}</div><p>{active?.title??"准备开始"}</p></div>{!active?<section className="focus-controls"><Field label="专注目标"><input value={title} onChange={e=>setTitle(e.target.value)}/></Field><div className="duration-row">{[25,45,60].map(x=><button className={minutes===x?"selected":""} onClick={()=>setMinutes(x)} key={x}>{x}<small>分钟</small></button>)}</div><Button icon="focus" onClick={start}>开始专注</Button></section>:<div className="focus-actions"><Button kind="secondary" onClick={active.status==="RUNNING"?pause:resume}>{active.status==="RUNNING"?"暂停":"继续"}</Button><Button onClick={finish}>结束并记录</Button></div>}<p className="focus-note">iPhone 锁屏或进入后台时，网页可能暂停运行；重新打开后会按开始时间恢复进度。环境音不保证后台持续。</p></div>;
}

function AchievementPage({data,commit,back}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void}) { const [name,setName]=useState(""),[target,setTarget]=useState(60);return <><PageHeader eyebrow="每一枚徽章都来自真实行动" title="成就馆" back={back}/><div className="achievement-grid">{builtInAchievements.map(x=>{const p=achievementProgress(data,x.id),done=p.value>=p.target;return <article className={done?"unlocked":""} key={x.id}><span className="badge" style={{background:x.primary}}>{x.icon}</span><h2>{x.name}</h2><p>{x.description}</p><progress value={p.value} max={p.target}/><small>{done?"已解锁":`${p.value}/${p.target}`}</small></article>})}{data.achievements.map(x=><article key={x.id}><span className="badge" style={{background:x.badge.primary}}>{x.badge.glyph||"✦"}</span><h2>{x.name}</h2><p>{x.description}</p><small>{x.unlockedAt?"已解锁":`目标 ${x.target}`}</small></article>)}</div><section className="panel"><h2>设计自己的成就</h2><Field label="成就名称"><input value={name} onChange={e=>setName(e.target.value)} placeholder="例如：期中冲刺"/></Field><Field label="累计专注分钟"><input type="number" min="10" value={target} onChange={e=>setTarget(Number(e.target.value))}/></Field><Button disabled={!name.trim()} onClick={async()=>{await commit({...data,achievements:[...data.achievements,{id:uid("achievement"),name:name.trim(),description:`累计专注 ${target} 分钟`,metric:"TOTAL_FOCUS_MINUTES",target,badge:{shape:"HEXAGON",primary:"#176B52",accent:"#FFC75F",icon:"star",glyph:name.trim().slice(0,1)}}]},"自定义成就已创建");setName("")}}>创建成就</Button></section></>; }

function ProfilePage({data,commit,back}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void}) { const [profile,setProfile]=useState(data.profile);const pick=async(f:File)=>{if(f.size>8_000_000){alert("头像不能超过 8 MB");return}const id=uid("avatar");await putAsset(id,f);setProfile({...profile,avatarAssetId:id})};return <><PageHeader eyebrow="校园资料全部只保存在本机" title="个人资料" back={back} action={<Button onClick={()=>commit({...data,profile},"个人资料已保存").then(back)}>保存</Button>}/><section className="editor-sheet"><div className="avatar-editor"><Avatar data={{...data,profile}} size={92}/><label className="button secondary file-button">选择头像<input type="file" accept="image/*" onChange={e=>{const f=e.target.files?.[0];if(f)pick(f)}}/></label></div><Field label="昵称"><input value={profile.nickname} onChange={e=>setProfile({...profile,nickname:e.target.value})}/></Field><Field label="问候语"><input value={profile.greeting} onChange={e=>setProfile({...profile,greeting:e.target.value})}/></Field><div className="form-grid"><Field label="NetID（选填）"><input value={profile.netId} onChange={e=>setProfile({...profile,netId:e.target.value})}/></Field><Field label="学号（选填）"><input value={profile.studentId} onChange={e=>setProfile({...profile,studentId:e.target.value})}/></Field></div><Field label="宿舍楼（选填）"><input value={profile.dorm} onChange={e=>setProfile({...profile,dorm:e.target.value})}/></Field><p className="help">这些资料不参与学校登录、不进入备份外的网络请求，也不会显示在通知中。</p></section></>; }

function SettingsPage({data,commit,back,go,standalone,install}:{data:WebAppData;commit:(x:WebAppData,m?:string)=>Promise<void>;back:()=>void;go:(x:string)=>void;standalone:boolean;install:()=>void}) {
  const [settings,setSettings]=useState(data.settings);const [notice,setNotice]=useState(""); const save=()=>commit({...data,settings},"设置已保存");
  const backup=async()=>{const payload=await exportBackup();const blob=new Blob([JSON.stringify(payload)],{type:"application/json"});const file=new File([blob],`中大课表完整备份-${shanghaiDate()}.json`,{type:blob.type});if(navigator.share&&navigator.canShare?.({files:[file]}))await navigator.share({title:"中大课表完整备份",files:[file]});else{const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}};
  const notify=async()=>{if(!standalone){setNotice("请先将网站添加到主屏幕，再从图标打开并授权通知。");return}if(!("Notification" in window)){setNotice("当前浏览器不支持 Web 通知。");return}try{const count=await enablePush({...data,settings});setNotice(`Web Push 已开启，已同步 ${count} 项未来提醒。`)}catch(e){setNotice(e instanceof Error?e.message:"通知未能开启")}};
  const background=async(f:File)=>{if(f.size>8_000_000){setNotice("启动背景不能超过 8 MB");return}const id=uid("launch");await putAsset(id,f);setSettings({...settings,launch:{...settings.launch,scene:"custom",backgroundAssetId:id}});setNotice("启动背景已保存到本机，点击“保存设置”生效。")};
  return <><PageHeader eyebrow="离线、外观与数据安全" title="个性化与设置" back={back} action={<Button onClick={save}>保存</Button>}/><section className="panel"><h2>校园配色</h2><Segmented value={settings.theme} onChange={theme=>setSettings({...settings,theme})} values={[["campus","康乐园绿"],["ocean","珠海海蓝"],["season","四季自动"]]}/><Field label="显示模式"><select value={settings.darkMode} onChange={e=>setSettings({...settings,darkMode:e.target.value as any})}><option value="system">跟随系统</option><option value="light">始终浅色</option><option value="dark">始终深色</option></select></Field></section><section className="panel"><h2>启动充能页</h2><label className="switch-row"><span><strong>启用长按充能</strong><small>按住芯核约 1.5 秒进入应用</small></span><input type="checkbox" checked={settings.launch.enabled} onChange={e=>setSettings({...settings,launch:{...settings.launch,enabled:e.target.checked}})}/></label><div className="scene-grid">{(["core","orbit","kapok"] as const).map((x,i)=><button className={settings.launch.scene===x?"selected":""} key={x} onClick={()=>setSettings({...settings,launch:{...settings.launch,scene:x}})}><i className={`scene-${x}`}/><span>{["山海芯核","星轨穹顶","木棉矩阵"][i]}</span></button>)}</div><label className="button secondary file-button">使用自己的照片<input type="file" accept="image/*" onChange={e=>{const f=e.target.files?.[0];if(f)background(f)}}/></label><div className="form-grid"><Field label="芯核颜色"><input type="color" value={settings.launch.coreColor} onChange={e=>setSettings({...settings,launch:{...settings.launch,coreColor:e.target.value}})}/></Field><Field label="光环颜色"><input type="color" value={settings.launch.haloColor} onChange={e=>setSettings({...settings,launch:{...settings.launch,haloColor:e.target.value}})}/></Field></div><Field label={`透明度 ${Math.round(settings.launch.opacity*100)}%`}><input type="range" min=".3" max="1" step=".05" value={settings.launch.opacity} onChange={e=>setSettings({...settings,launch:{...settings.launch,opacity:Number(e.target.value)}})}/></Field><Field label={`光效强度 ${Math.round(settings.launch.intensity*100)}%`}><input type="range" min="0" max="1" step=".05" value={settings.launch.intensity} onChange={e=>setSettings({...settings,launch:{...settings.launch,intensity:Number(e.target.value)}})}/></Field></section><section className="panel"><h2>笔记默认外观</h2><AppearanceControls value={settings.noteStyle} onChange={noteStyle=>setSettings({...settings,noteStyle})}/></section><section className="panel"><h2>提醒与 Apple 日历</h2><p>Apple 日历是最稳妥的课前提醒补充。课表或待办变化后请重新导出，并在日历中移除旧版本。</p><div className="actions"><Button kind="secondary" onClick={()=>downloadCalendar(data).then(()=>setNotice("日历文件已生成，请选择 Apple 日历打开。"))}>导出 ICS 日历</Button><Button kind="secondary" onClick={notify}>开启 Web 通知</Button></div><details><summary>推送服务配置（内测）</summary><Field label="HTTPS 服务地址"><input value={settings.pushEndpoint} onChange={e=>setSettings({...settings,pushEndpoint:e.target.value})} placeholder="https://push.example.com"/></Field><Field label="VAPID 公钥"><textarea className="resize-none" value={settings.pushPublicKey} onChange={e=>setSettings({...settings,pushPublicKey:e.target.value})} rows={3}/></Field><p className="help">未配置服务器时不会上传任何数据，也不会显示为“推送已启用”。服务器只应保存匿名订阅、触发时间与密文。</p></details>{notice&&<p className="notice-inline">{notice}</p>}</section><section className="panel"><h2>完整数据备份</h2><p>Safari 网站数据和主屏幕应用存储不能当作永久备份。换机、清理浏览器或卸载前请导出。</p><div className="actions"><Button kind="secondary" onClick={backup}>导出完整备份 V2</Button><label className="button secondary file-button">恢复完整备份<input type="file" accept=".json,application/json" onChange={async e=>{const f=e.target.files?.[0];e.target.value="";if(!f)return;try{const restored=await importBackup(JSON.parse(await f.text()));await commit(restored,"完整备份已恢复");location.reload()}catch(err){setNotice(err instanceof Error?err.message:"备份恢复失败")}}}/></label></div></section><section className="panel"><h2>安装与离线</h2><p>{standalone?"当前正从主屏幕 Web App 打开。":"当前在浏览器中打开，建议先添加到主屏幕。"}</p>{!standalone&&<Button kind="secondary" onClick={install}>添加到主屏幕</Button>}<Button kind="text" onClick={()=>go("/import")}>前往课表导入</Button></section><section className="panel about"><h2>关于作者</h2><p><strong>xiaoyle · 集成电路学院</strong></p><a href="https://github.com/xiaoyle" target="_blank" rel="noreferrer">GitHub ↗</a><a href="https://xiaoyle.github.io/CampusSchedule/" target="_blank" rel="noreferrer">项目网站 ↗</a><a href="https://github.com/xiaoyle/CampusSchedule/issues" target="_blank" rel="noreferrer">问题反馈 ↗</a><p>博客：筹备中</p><button className="text-button" onClick={()=>navigator.clipboard.writeText("abc135235435").then(()=>setNotice("微信号已复制"))}>微信 abc135235435 · 复制</button><a href="tel:13726492826">手机 13726492826 · 打开拨号盘</a></section></>;
}

function LaunchGate({data,done}:{data:WebAppData;done:()=>void}) {
  const [progress,setProgress]=useState(0),frame=useRef(0),start=useRef(0),[background,setBackground]=useState("");
  useEffect(()=>{let url="";readAsset(data.settings.launch.backgroundAssetId).then(blob=>{if(blob){url=URL.createObjectURL(blob);setBackground(url)}});return()=>{if(url)URL.revokeObjectURL(url);cancelAnimationFrame(frame.current)}},[]);
  const stop=()=>{cancelAnimationFrame(frame.current);if(progress<1){const from=progress,at=performance.now();const back=(t:number)=>{const p=Math.max(0,from*(1-(t-at)/260));setProgress(p);if(p>0)frame.current=requestAnimationFrame(back)};frame.current=requestAnimationFrame(back)}};
  const hold=()=>{cancelAnimationFrame(frame.current);start.current=performance.now();const step=(t:number)=>{const p=Math.min(1,(t-start.current)/1500);setProgress(p);if(p>=1){navigator.vibrate?.(28);setTimeout(done,180)}else frame.current=requestAnimationFrame(step)};frame.current=requestAnimationFrame(step)};
  const style={"--charge":`${progress*360}deg`,"--core":data.settings.launch.coreColor,"--halo":data.settings.launch.haloColor,"--core-opacity":data.settings.launch.opacity,"--intensity":data.settings.launch.intensity,backgroundImage:background?`linear-gradient(#071b24aa,#071b24cc),url(${background})`:undefined} as React.CSSProperties;
  return <div className={`launch-gate scene-${data.settings.launch.scene}`} style={style}><div className="launch-copy"><span>中大课表</span><small>把今天握在手中</small></div><div className="charge-core" role="button" tabIndex={0} aria-label="按住约一点五秒进入中大课表" onPointerDown={hold} onPointerUp={stop} onPointerCancel={stop} onPointerLeave={stop} onKeyDown={e=>{if((e.key===" "||e.key==="Enter")&&!e.repeat){e.preventDefault();hold()}}} onKeyUp={e=>{if(e.key===" "||e.key==="Enter"){e.preventDefault();stop()}}} onContextMenu={e=>e.preventDefault()}><i/><strong>{progress>=1?"已连接":"按住充能"}</strong><small>{Math.round(progress*100)}%</small></div><p>持续按住约 1.5 秒</p></div>;
}
